package com.ejemplo.alquileres.seeder;
import com.ejemplo.alquileres.model.*; import com.ejemplo.alquileres.repository.*; import com.ejemplo.alquileres.service.InmuebleService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import java.math.BigDecimal;
@Component @RequiredArgsConstructor public class InmuebleSeeder {private final InmuebleRepository repo;private final TipoInmuebleRepository tipos;private final PropietarioRepository propietarios;private final InmuebleService service;
 public void cargar(){String[][] d={{"INM-0001","Depa 301 · Av. Lima","TI-DEP","DISPONIBLE","1850"},{"INM-0002","Casa Los Olivos","TI-CAS","DISPONIBLE","3200"},{"INM-0003","Local Miraflores","TI-LOC","MANTENIMIENTO","4200"},{"INM-0004","Oficina San Isidro","TI-OFI","DISPONIBLE","2800"},{"INM-0005","Cochera 15","TI-COC","DISPONIBLE","380"},{"INM-0006","Habitación Barranco","TI-HAB","DISPONIBLE","900"},{"INM-0007","Terreno Lurín","TI-TER","INACTIVO","1500"},{"INM-0008","Depa 502 · Jesús María","TI-DEP","DISPONIBLE","2100"},{"INM-0009","Casa Pueblo Libre","TI-CAS","DISPONIBLE","2950"},{"INM-0010","Local Surco","TI-LOC","DISPONIBLE","3600"}};var propietario=propietarios.findAll().stream().findFirst().orElse(null);for(String[] x:d)if(!repo.existsByCodigoIgnoreCase(x[0]))service.guardar(Inmueble.builder().codigo(x[0]).nombre(x[1]).tipo(tipos.findAll().stream().filter(t->t.getCodigo().equals(x[2])).findFirst().orElse(null)).propietario(propietario).direccion("Dirección ficticia " + x[0]).distrito("Lima").areaM2(new BigDecimal("60.00")).dormitorios(2).banos(1).estacionamientos(0).rentaReferencial(new BigDecimal(x[4])).estado(EstadoInmueble.valueOf(x[3])).build());}}
